const FormSection = ({
    name,
    email,
    setName,
    setEmail,
    onSubmit,
}: any) => {
    return (
        <div className="form">
            <h2>Update Info</h2>

            <FormField
                label="Name"
                value={name}
                onChange={(v: string) => setName(v)}
            />

            <FormField
                label="Email"
                value={email}
                onChange={(v: string) => setEmail(v)}
            />

            <Button onClick={onSubmit}>Save</Button>
        </div>
    );
};

const FormField = ({ label, value, onChange }: any) => {
    return (
        <div className="field">
            <label>{label}</label>
            <Input value={value} onChange={onChange} />
        </div>
    );
};

const Input: React.FC<IInputProps> = (props) => {
    const {
        defaultValue,
        onClick,
        onChange,
        inputRef,
        disabled,
        label,
        placeholder,
        type = "text",
    } = props;

    return (
        <div style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
            {label && <label>{label}</label>}

            <input
                ref={inputRef as any}
                defaultValue={defaultValue}
                onClick={onClick}
                onChange={onChange}
                disabled={disabled}
                placeholder={placeholder}
                type={type}
                style={{
                    padding: "8px",
                    borderRadius: "6px",
                    border: "1px solid #ccc",
                }}
            />
        </div>
    );
};

const Tree: React.FC<TreeProps> = ({ data }) => {
    return (
        <ul>
            {data.map(node => (
                <TreeNode key={node.id} node={node} />
            ))}
        </ul>
    );
};

const TreeNode: React.FC<Props> = ({ node }) => {
    return (
        <li>
            {node.label}
            {node.children && (
                <ul>
                    {node.children.map(child => (
                        <TreeNode key={child.id} node={child} />
                    ))}
                </ul>
            )}
        </li>
    );
};
